import dlarfb = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const V = new Float64Array( 9 );
	const T = new Float64Array( 9 );
	const C = new Float64Array( 9 );
	const work = new Float64Array( 9 );

	dlarfb( 'column-major', 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const V = new Float64Array( 9 );
	const T = new Float64Array( 9 );
	const C = new Float64Array( 9 );
	const work = new Float64Array( 9 );

	dlarfb( 5, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( true, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( false, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( null, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( void 0, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( [], 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( {}, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
	dlarfb( ( x: number ): number => x, 'left', 'no-transpose', 'forward', 'columns', 3, 3, 3, V, 3, T, 3, C, 3, work, 3 ); // $ExpectError
}

